    input = sys.stdin.read().split()
    n = int(input[0])
    m = int(input[1])
    k = int(input[2])
    w = int(input[3])
    levels = [''.join(input[i * n + 4:(i + 1) * n + 4]) for i in range(k)]

    def diff_count(level1, level2):
        return sum(1 for a, b in zip(level1, level2) if a != b)

    dp = [[float('inf')] * k for _ in range(k)]
    for i in range(k):
        dp[i][i] = 0

    for length in range(2, k + 1):
        for i in range(k - length + 1):
            j = i + length - 1
            for p in range(i, j):
                dp[i][j] = min(dp[i][j], dp[i][p] + diff_count(levels[p], levels[j]))

    min_bytes = float('inf')
    transfers = []
    for i in range(k):
        total_bytes = n * m + dp[0][i]
        for j in range(i + 1, k):
            total_bytes += dp[i + 1][j] * w
        if total_bytes < min_bytes:
            min_bytes = total_bytes
            transfers = [(1, 0)]
            current = i
            for j in range(i + 1, k):
                min_diff = float('inf')
                prev = None
                for p in range(i, j):
                    diff = diff_count(levels[p], levels[j])
                    if dp[p + 1][j] + diff == dp[i + 1][j]:
                        if diff < min_diff:
                            min_diff = diff
                            prev = p + 1
                transfers.append((prev, prev))
                current = prev
            for j in range(current + 1, k):
                transfers.append((j + 1, j))

    print(min_bytes)
    for x, y in transfers:
